ns\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/1/21-22/\",\"title\":\"TEXTS 21-22\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":293,\"bb\":567903,\"url_path\":\"/en/library/bg/1/20/devanagari/\",\"body_final\":\"अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः ।
प्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः ।
हृषीकेशं तदा वाक्यमिदमाह महीपते ॥ २० ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":294,\"bb\":271,\"url_path\":\"/en/library/bg/1/20/b271/\",\"body_value\":\"atha vyavasthitān dṛṣṭvā
dhārtarāṣṭrān kapi-dhvajaḥ
pravṛtte śastra-sampāte
dhanur udyamya pāṇḍavaḥ
hṛṣīkeśaṁ tadā vākyam
idam āha mahī-pate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":295,\"bb\":272,\"url_path\":\"/en/library/bg/1/20/b272/\",\"shadow_value\":\"atha – thereupon; vyavasthitān – situated; dṛṣṭvā – looking upon; dhārtarāṣṭrān – the sons of Dhṛtarāṣṭra; kapi-dhvajaḥ – he whose flag was marked with Hanumān; pravṛtte – while about to engage; śastra-sampāte – in releasing his arrows; dhanuḥ – bow; udyamya – taking up; pāṇḍavaḥ – the son of Pāṇḍu (Arjuna); hṛṣīkeśam – unto Lord Kṛṣṇa; tadā – at that time; vākyam – words; idam – these; āha – said; mahī-pate – O King.\",\"word_for_word_value\":[{\"word\":\"atha\",\"translation\":\"thereupon\"},{\"word\":\"vyavasthitān\",\"translation\":\"situated\"},{\"word\":\"dṛṣṭvā\",\"translation\":\"looking upon\"},{\"word\":\"dhārtarāṣṭrān\",\"translation\":\"the sons of Dhṛtarāṣṭra\"},{\"word\":\"kapi-dhvajaḥ\",\"translation\":\"he whose flag was marked with Hanumān\"},{\"word\":\"pravṛtte\",\"translation\":\"while about to engage\"},{\"word\":\"śastra-sampāte\",\"translation\":\"in releasing his arrows\"},{\"word\":\"dhanuḥ\",\"translation\":\"bow\"},{\"word\":\"udyamya\",\"translation\":\"taking up\"},{\"word\":\"pāṇḍavaḥ\",\"translation\":\"the son of Pāṇḍu (Arjuna)\"},{\"word\":\"hṛṣīkeśam\",\"translation\":\"unto Lord Kṛṣṇa\"},{\"word\":\"tadā\",\"translation\":\"at that time\"},{\"word\":\"vākyam\",\"translation\":\"words\"},{\"word\":\"idam\",\"translation\":\"these\"},{\"word\":\"āha\",\"translation\":\"said\"},{\"word\":\"mahī-pate\",\"translation\":\"O King\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":296,\"bb\":273,\"url_path\":\"/en/library/bg/1/20/b273/\",\"body_value\":\"At that time Arjuna, the son of Pāṇḍu, seated in the chariot bearing the flag marked with Hanumān, took up his bow and prepared to shoot his arr